!function(){
    var B = "https://www.adotrip.com/hotel-details/",
        c = document.getElementById("hotelResultsContainer"),
        t = document.getElementById("hotelCardTpl");

    function q(e, k) {
        return e.querySelector('[data-f="' + k + '"]');
    }

    function x(e, k, v) {
        var el = q(e, k);
        if (el) el.textContent = v;
    }

    function card(h) {
        var e = t.content.firstElementChild.cloneNode(true),
            g = h.images || [],
            i, a, m, s, p,
            l = h.name + " Adotrip";

        e.dataset.rating = h.rating;
        e.dataset.name = h.name;
        e.dataset.amenities = h.amenities;
        e.dataset.price = h.basePrice || h.price;

        if (g.length > 0) {
            var mainLink = q(e, "mainLink");
            if (mainLink) mainLink.href = g[0];
            m = q(e, "mainImg");
            if (m) {
                m.src = g[0];
                m.alt = m.title = l;
            }
        }

        var thumbsContainer = q(e, "thumbs");
        if (thumbsContainer) {
            for (i = 1; i < g.length; i++) {
                a = document.createElement("a");
                a.target = "_blank";
                a.rel = "noopener";
                a.href = g[i];
                m = new Image();
                m.src = g[i];
                m.alt = m.title = l;
                a.appendChild(m);
                thumbsContainer.appendChild(a);
            }
        }

        x(e, "name", h.name);

        var starsEl = q(e, "stars");
        if (starsEl) {
            for (i = 0; i < (h.rating || 5); i++) {
                s = document.createElement("i");
                s.className = "fa-solid fa-star text-warning";
                starsEl.appendChild(s);
            }
        }

        x(e, "address", (h.address || "").replace(/[,\s]+$/, ""));
        x(e, "region", "India > " + (h.region || "Delhi"));

        var amenEl = q(e, "amenities");
        if (amenEl && h.amenities) {
            h.amenities.split(",").forEach(function(v) {
                p = document.createElement("p");
                p.className = "text-dark mb-1";
                s = document.createElement("span");
                s.className = "badge border";
                s.textContent = v.trim().replace(/\b\w/g, function(z) { return z.toUpperCase(); });
                p.appendChild(s);
                amenEl.appendChild(p);
            });
        }

        x(e, "inclusions", h.inclusions || "Complimentary WiFi, Valet Parking");
        x(e, "meal", h.meal || "Not specified");
        
        var promoEl = q(e, "promo");
        if (promoEl) {
            promoEl.textContent = h.promo || "Best rate guarantee";
        }

        x(e, "ratingLabel", "Excellent");
        x(e, "reviews", h.reviews || 180);
        x(e, "price", (h.price || "").toLocaleString ? Number(h.price).toLocaleString('en-IN') : h.price);

        var btn = e.querySelector(".hotel-book-btn");
        if (btn) {
            btn.dataset.url = B + (h.slug || "");
        }

        return e;
    }

    fetch("hotels.json")
        .then(function(r) { return r.json(); })
        .then(function(d) {
            // Remove skeleton cards once data arrives
            c.innerHTML = "";
            var f = document.createDocumentFragment();
            d.forEach(function(h) {
                f.appendChild(card(h));
            });
            c.appendChild(f);

            // Re-initialize LightGallery if available
            if (window.lightGallery) {
                c.querySelectorAll(".lightgallery").forEach(function(el) {
                    lightGallery(el, {
                        selector: "a",
                        thumbnail: true
                    });
                });
            }
        })
        .catch(function(err) {
            console.error(err);
            c.innerHTML = '<div class="alert alert-warning text-center my-4">Unable to load hotels at this moment. Please try again.</div>';
        });
}();
